class TestThresholdCounter:
    def test_invalid_threshold(self):
        with pytest.raises(ValueError):
            ThresholdCounter(threshold=0)
        with pytest.raises(ValueError):
            ThresholdCounter(threshold=1)
        with pytest.raises(ValueError):
