    def test_threshold_property(self):
        tc = ThresholdCounter(threshold=0.1)
        assert tc.threshold == 0.1

    def test_add_and_get(self):
        tc = ThresholdCounter(threshold=0.1)
        tc.add(1)
        assert tc[1] == 1
        tc.add(1)
        assert tc[1] == 2
        assert tc.total == 2

    def test_contains(self):
        tc = ThresholdCounter(threshold=0.1)
        tc.add('x')
        assert 'x' in tc
        assert 'y' not in tc

    def test_get_default(self):
        tc = ThresholdCounter(threshold=0.1)
        assert tc.get('missing') == 0
        assert tc.get('missing', 99) == 99

    def test_len(self):
        tc = ThresholdCounter(threshold=0.1)
        assert len(tc) == 0
        tc.add(1)
        tc.add(2)
        assert len(tc) == 2

    def test_keys_values_items(self):
        tc = ThresholdCounter(threshold=0.5)
        tc.add(1)
        tc.add(1)
        tc.add(2)
        assert sorted(tc.keys()) == [1, 2]
        assert sorted(tc.values()) == [1, 2]
        assert sorted(tc.items()) == [(1, 2), (2, 1)]

    def test_elements(self):
        tc = ThresholdCounter(threshold=0.5)
        tc.add(1)
        tc.add(1)
        tc.add(2)
        elems = sorted(tc.elements())
        assert elems == [1, 1, 2]

    def test_most_common(self):
        tc = ThresholdCounter(threshold=0.5)
        tc.add(1)
        tc.add(1)
        tc.add(2)
        assert tc.most_common() == [(1, 2), (2, 1)]
        assert tc.most_common(1) == [(1, 2)]
        assert tc.most_common(0) == []
        assert tc.most_common(-1) == []
        assert tc.most_common(10) == [(1, 2), (2, 1)]

    def test_update_iterable(self):
        tc = ThresholdCounter(threshold=0.1)
        tc.update([1, 1, 2])
        assert tc[1] == 2
        assert tc[2] == 1
        assert tc.total == 3

    def test_update_mapping(self):
        tc = ThresholdCounter(threshold=0.1)
        tc.update({1: 2, 2: 1})
        assert tc[1] == 2
        assert tc[2] == 1
        assert tc.total == 3

    def test_update_kwargs(self):
        tc = ThresholdCounter(threshold=0.1)
        tc.update([], a=3)
        assert tc['a'] == 3

    def test_update_none(self):
        tc = ThresholdCounter(threshold=0.1)
        tc.update(None)
        assert tc.total == 0

    def test_common_counts(self):
        tc = ThresholdCounter(threshold=0.1)
        tc.add(1)
        tc.add(1)
        assert tc.get_common_count() == 2
        assert tc.get_uncommon_count() == 0
        assert tc.get_commonality() == 1.0

    def test_compaction(self):
        tc = ThresholdCounter(threshold=0.2)  # thresh_count = 5
        for _ in range(5):
            tc.add(1)
        # after first bucket, common count kept
        assert tc[1] == 5

    def test_compaction_drops_rare(self):
        tc = ThresholdCounter(threshold=0.2)  # thresh_count = 5
        tc.add('rare')
        for _ in range(4):
            tc.add('common')
        # now total == 5, compaction happens
        # 'rare' count is 1, sum = 1, curt bucket 0 -> 1 > 0 kept
        # add more common so rare gets dropped
        for _ in range(5):
            tc.add('common')
        # after second compaction, rare dropped
        assert 'rare' not in tc
        assert 'common' in tc
        assert tc.get_uncommon_count() > 0

    def test_uncommon_count_no_division_by_zero_when_empty(self):
        tc = ThresholdCounter(threshold=0.1)
        assert tc.get_common_count() == 0
        assert tc.get_uncommon_count() == 0


