        a = self.Obj()
        assert a not in m
        m.get(a)
        assert a in m

    def test_iter(self):
        m = MinIDMap()
        a, b = self.Obj(), self.Obj()
        m.get(a)
        m.get(b)
        assert set(iter(m)) == {a, b}

